func valueLink(p unsafe.Pointer, c int32) any {
	r := (*customertracking.Link)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.CustomerID)
	case 5:
		return r.TokenHash
	case 6:
		return string(r.Purpose)
	case 7:
		if r.RecipientEmail == "" {
			return nil
		}
		return r.RecipientEmail
	case 8:
		return r.ExpiresAt
	case 9:
		if r.RevokedAt == nil {
			return nil
		}
		return *r.RevokedAt
	case 10:
		if r.LastViewedAt == nil {
			return nil
		}
		return *r.LastViewedAt
	case 11:
		return r.ViewCount
	case 12:
		if r.CreatedByID == "" {
			return nil
		}
		return string(r.CreatedByID)
	case 13:
		return r.CreatedAt
	case 14:
		return r.UpdatedAt
	}
	return nil
}

