func newNotification() unsafe.Pointer { return unsafe.Pointer(new(customertracking.Notification)) }

func newNNotification(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]customertracking.Notification, n)))
}

func ptrNotification(p unsafe.Pointer, c int32) any {
	r := (*customertracking.Notification)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 2:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ShipmentID))
	case 4:
		return (*string)(unsafe.Pointer(&r.CustomerID))
	case 5:
		return (*string)(unsafe.Pointer(&r.Event))
	case 6:
		return &r.SubjectKey
	case 7:
		return (*string)(unsafe.Pointer(&r.StopID))
	case 8:
		return &r.OccurredAt
	case 9:
		return &r.EstimatedAt
	case 10:
		return (*string)(unsafe.Pointer(&r.Status))
	case 11:
		return (*string)(unsafe.Pointer(&r.SkipReason))
	case 12:
		return &r.Recipients
	case 13:
		return (*string)(unsafe.Pointer(&r.LinkID))
	case 14:
		return (*string)(unsafe.Pointer(&r.EmailMessageID))
	case 15:
		return &r.Attempts
	case 16:
		return &r.LastError
	case 17:
		return &r.NextAttemptAt
	case 18:
		return &r.SentAt
	case 19:
		return &r.CreatedAt
	case 20:
		return &r.UpdatedAt
	}
	return nil
}

func valueNotification(p unsafe.Pointer, c int32) any {
	r := (*customertracking.Notification)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.OrganizationID)
	case 2:
		return string(r.BusinessUnitID)
	case 3:
		return string(r.ShipmentID)
	case 4:
		return string(r.CustomerID)
	case 5:
		return string(r.Event)
	case 6:
		return r.SubjectKey
	case 7:
		if r.StopID == "" {
			return nil
		}
		return string(r.StopID)
	case 8:
		return r.OccurredAt
	case 9:
		if r.EstimatedAt == nil {
			return nil
		}
		return *r.EstimatedAt
	case 10:
		return string(r.Status)
	case 11:
		if r.SkipReason == "" {
			return nil
		}
		return string(r.SkipReason)
	case 12:
		if r.Recipients == nil {
			return []string{}
		}
		return r.Recipients
	case 13:
		if r.LinkID == "" {
			return nil
		}
		return string(r.LinkID)
	case 14:
		if r.EmailMessageID == "" {
			return nil
		}
		return string(r.EmailMessageID)
	case 15:
		return r.Attempts
	case 16:
		if r.LastError == "" {
			return nil
		}
		return r.LastError
	case 17:
		return r.NextAttemptAt
	case 18:
		if r.SentAt == nil {
			return nil
		}
		return *r.SentAt
	case 19:
		return r.CreatedAt
	case 20:
		return r.UpdatedAt
	}
	return nil
}

